'use strict';

// MODULES //

import sin from '@stdlib/math/base/special/sin';
import PI from '@stdlib/constants/float64/pi';
import floor from '@stdlib/math/base/special/floor';
import rffti from './../../../../../base/fftpack/generic/rffti';


// MAIN //

/**
* Initializes a workspace array for performing a sine transform.
*
* ## Notes
*
* The workspace array is divided into four sections:
*
* ```text
*       size = N/2         N+1                 N+1         2+ceil(log2(N+1)/2)
*            ↓              ↓                   ↓                   ↓
*     | sine table | scratch/workspace | twiddle factors | radix factor table |
*            ↑              ↑                   ↑                   ↑
* i = 0     ...   N/2      ...      (3N/2)+1   ...    (5N/2)+2     ...
* ```
*
* where
*
* -   **sine table**: a table of precomputed sine coefficients used by sine transforms.
* -   **scratch/workspace**: used as a scratch space when performing transforms. This section is not updated during initialization.
* -   **twiddle factors**: a table of reusable complex-exponential constants stored as cosine/sine pairs.
* -   **radix factor table**: a table containing the radix factorization of `N+1`.
*
* In general, a workspace array should have `2.5N + 34` indexed elements (as `log2(N+1)/2 ≤ 32` for all `2^64`). During initialization, only the sections for storing the sine coefficients, twiddle factors, and the factorization of `N+1` are updated.
*
* > Note: FFTPACK only requires `2.5N+15`, but we increase that number here to accommodate larger workspace arrays, where `N` may exceed `2^30` indexed elements.
*
* The factorization section is comprised as follows:
*
* ```text
* | sequence_length | number_of_factors | integer_factors |
* ```
*
* The sequence length and number of factors (`nf`) comprise a single element each. Only the first `nf` elements in the integer factors section are written to, with the rest being unused.
*
* As for twiddle factors, these are small, reusable complex-exponential constants that appear inside each "butterfly" stage of a Cooley–Tukey–style FFT. Every arithmetic step in an FFT multiplies one intermediate value by some
*
* ```tex
* W_N^k
* ```
*
* where `W_N^k` is an N-th root of unity. Formally, in a forward FFT,
*
* ```tex
* W_N^k = e^{-2\pi ik/N}
* ```
*
* In a backward FFT,
*
* ```tex
* W_N^k = e^{+2\pi ik/N}
* ```
*
* As may be observed, `W_N^k` for forward and backward FFTs is the same, except the sign of the exponent is flipped. As a consequence, both forward and backward FFT callers can reuse the same set of twiddle factors, with those performing a forward transform multiplying with `(cos,-sin)` and those performing a backward transform multiplying with `(cos,+sin)`.
*
* Because these constants only depend on the transform length `N` (and **not** on the input data), we can pre-compute and store them once, then "twiddle" them (i.e., reuse them with different indices) as we proceed through the factorization.
*
* > As a quick aside regarding the name "twiddle", early FFT papers (notably Gentleman & Sande, 1966) described how you "twiddle" one branch of each butterfly by a complex rotation before adding/subtracting. The coefficients themselves inherited the nickname "twiddle factors," and the term stuck.
*
* By reusing the workspace array when computing multiple transforms of the same length `N`, every subsequent `*f` (forward) or `*b` (backward) call can simply look up the pre-stored twiddle factors instead of recomputing sine and cosine on-the-fly.
*
* In short, twiddle factors are cached roots of unity that allow each stage of the algorithm to rotate data quickly and predictably.
*
* During initialization, `sinti` first writes the sine table, and then initializes the remaining three sections using `rffti`.
*
* @param {PositiveInteger} N - length of the sequence to transform
* @param {Collection} workspace - workspace array
* @param {integer} strideW - stride length for `workspace`
* @param {NonNegativeInteger} offsetW - starting index for `workspace`
* @returns {Collection} workspace array
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import floor from '@stdlib/math/base/special/floor';
*
* var N = 7;
* var workspace = new Float64Array( floor( 2.5*N ) + 34 );
*
* var out = sinti( N, workspace, 1, 0 );
* // returns <Float64Array>
*
* var bool = ( out === workspace );
* // returns true
*
* var sineTable = workspace.slice( 0, floor( N/2 ) );
* // returns <Float64Array>[ ~0.765, ~1.414, ~1.848 ]
*
* var twiddleFactors = workspace.slice( floor( 3*N/2 ) + 1, floor( 5*N/2 ) + 2 );
* // returns <Float64Array>[ ~0.707, ~0.707, 0, 0, 0, 0, 0, 0 ]
*
* var factors = workspace.slice( floor( 5*N/2 ) + 2, floor( 5*N/2 ) + 2 + 4 );
* // returns <Float64Array>[ 8, 2, 2, 4 ]
*/
function sinti( N, workspace, strideW, offsetW ) {
	var offsetR;
	var ns2;
	var dt;
	var fk;
	var iw;
	var i;

	if ( N <= 1 ) {
		return workspace;
	}

	// Compute the number of sine values to store:
	ns2 = floor( N / 2 );

	// Compute the angular increment:
	dt = PI / ( N + 1 );

	// Compute and store the sine table:
	fk = 0.0;
	iw = offsetW;
	for ( i = 0; i < ns2; i++ ) {
		fk += 1.0;
		workspace[ iw+(i*strideW) ] = sin( fk*dt ) * 2.0;
	}
	// Resolve the starting index for the `rffti` workspace:
	offsetR = offsetW + (ns2*strideW);

	// Initialize the real FFT workspace for a sequence of length N+1:
	rffti( N+1, workspace, strideW, offsetR );

	return workspace;
}


// EXPORTS //

export default sinti;
